 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The repeated edge bars are guide rails; a singleton marker's column/row
    # selects its aligned rail slot. The marker's color is projected along that
    # slot from the rail, while the marker itself becomes 4.
    colors = {}
    for row in grid:
        for value in row:
            colors[value] = colors.get(value, 0) + 1
    bg = max(colors, key=colors.get)

    def bars(line):
        found=[]; i=0
        while i < len(line):
            if line[i] == bg:
                i += 1
                continue
            color, start = line[i], i
            i += 1
            while i < len(line) and line[i] == color:
                i += 1
            if i-start >= 2:
                found.append((color, start, i))
        return found

    edge = {
        'top': bars(grid[0]),
        'bottom': bars(grid[-1]),
        'left': bars([grid[r][0] for r in range(h)]),
        'right': bars([grid[r][-1] for r in range(h)]),
    }
    for a,b in (('top','bottom'), ('left','right')):
        for ca,sa,ea in edge[a]:
            for cb,sb,eb in edge[b]:
                if ca != cb or ea-sa != eb-sb:
                    continue
                for r in range(1,h-1):
                    for c in range(1,w-1):
                        marker = grid[r][c]
                        if marker == bg:
                            continue
                        axis = c if a == 'top' else r
                        if sa <= axis < ea:
                            source, s0, target, t0 = a, sa, b, sb
                        elif sb <= axis < eb:
                            source, s0, target, t0 = b, sb, a, sa
                        else:
                            continue
                        target_pos = t0 + axis - s0
                        if a == 'top':
                            # Draw from the marker toward the nearest matched rail.
                            if source == 'top':
                                for rr in range(1, r):
                                    out[rr][c] = marker
                            else:
                                for rr in range(r+1, h-1):
                                    out[rr][c] = marker
                            out[r][c] = 4
                            # Draw on the paired rail's interior from its inner edge
                            # to the opposite boundary; the rail itself is preserved.
                            if target == 'top':
                                for rr in range(1,h-1):
                                    out[rr][target_pos] = marker
                            else:
                                for rr in range(1,h-1):
                                    out[rr][target_pos] = marker
                        else:
                            if source == 'left':
                                for cc in range(1,c):
                                    out[r][cc] = marker
                            else:
                                for cc in range(c+1,w-1):
                                    out[r][cc] = marker
                            out[r][c] = 4
                            for cc in range(1,w-1):
                                out[target_pos][cc] = marker
    return out

