 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    def edge_runs(line):
        result = []
        i = 0
        while i < len(line):
            if line[i] == bg:
                i += 1
                continue
            color, start = line[i], i
            i += 1
            while i < len(line) and line[i] == color:
                i += 1
            if i - start >= 2:
                result.append((color, start, i))
        return result

    tops, bottoms = edge_runs(grid[0]), edge_runs(grid[-1])
    lefts = edge_runs([grid[r][0] for r in range(h)])
    rights = edge_runs([grid[r][-1] for r in range(h)])

    # Matching bars on opposite edges identify corresponding phases of a
    # periodic line motif. A marker in that phase gets projected along its own
    # line to its nearest matching boundary; the paired phase gets the full
    # complementary stripe, retaining existing non-background guide cells.
    for bars_a, bars_b, horizontal in ((tops, bottoms, True), (lefts, rights, False)):
        for color, start_a, end_a in bars_a:
            for color_b, start_b, end_b in bars_b:
                if color != color_b or end_a - start_a != end_b - start_b:
                    continue
                for r in range(1, h - 1):
                    for c in range(1, w - 1):
                        marker = grid[r][c]
                        if marker == bg:
                            continue
                        axis = c if horizontal else r
                        if start_a <= axis < end_a:
                            source_a = True
                            offset = axis - start_a
                        elif start_b <= axis < end_b:
                            source_a = False
                            offset = axis - start_b
                        else:
                            continue
                        paired = (start_b if source_a else start_a) + offset
                        if horizontal:
                            if source_a:
                                for rr in range(1, r):
                                    if grid[rr][c] == bg:
                                        out[rr][c] = marker
                            else:
                                for rr in range(r + 1, h - 1):
                                    if grid[rr][c] == bg:
                                        out[rr][c] = marker
                            out[r][c] = 4
                            for rr in range(h):
                                if grid[rr][paired] == bg:
                                    out[rr][paired] = marker
                        else:
                            if source_a:
                                for cc in range(1, c):
                                    if grid[r][cc] == bg:
                                        out[r][cc] = marker
                            else:
                                for cc in range(c + 1, w - 1):
                                    if grid[r][cc] == bg:
                                        out[r][cc] = marker
                            out[r][c] = 4
                            for cc in range(w):
                                if grid[paired][cc] == bg:
                                    out[paired][cc] = marker
    return out

if __name__ == '__main__':
    pass
